sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	var parent_sys_id = current.parent;
	var grCases = new GlideRecord("x_hccc_hoc_ohs_investigation_case");
	grCases.addQuery('parent',parent_sys_id);
	grCases.addQuery('state','!=',902);//Completed
	grCases.query();

	var hasUncompletedCase = false;
	while (grCases.next()) { 
		hasUncompletedCase = true;
	}

	if (hasUncompletedCase == false){
		var grParentCase = new GlideRecord("x_hccc_hoc_ohs_investigation_case");
		grParentCase.addQuery('sys_id',parent_sys_id);
		grParentCase.query();
		while (grParentCase.next()) { 
			grParentCase.state = 902;
			grParentCase.update();
		}
	}


})(current, previous);
